#include <stdio.h>
#include <string.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char S[1005];
    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        S[i] = '0' + d;
    }
    S[N] = '\0';

    // Tenta todos os possíveis comprimentos L para o primeiro número A.
    // O primeiro L que funcionar fornece o menor A, pois números com menos
    // dígitos são sempre menores que números com mais dígitos.
    for (int L = 1; L <= N; L++) {
        char cur[1005];
        strncpy(cur, S, L);
        cur[L] = '\0';
        int len = L;
        int pos = 0;
        int ok = 1;

        while (pos < N) {
            if (pos + len > N) {
                ok = 0;
                break;
            }
            if (strncmp(cur, S + pos, len) != 0) {
                ok = 0;
                break;
            }
            pos += len;
            if (pos == N) break;

            // Incrementa o número atual (cur) em 1.
            int i = len - 1;
            while (i >= 0 && cur[i] == '9') {
                cur[i] = '0';
                i--;
            }
            if (i < 0) {
                // Ocorreu carry out (ex: 99 -> 100).
                for (int j = len; j > 0; j--) {
                    cur[j] = cur[j - 1];
                }
                cur[0] = '1';
                len++;
                cur[len] = '\0';
            } else {
                cur[i]++;
            }
        }

        if (ok && pos == N) {
            // Encontramos o menor A. Imprime os L primeiros dígitos de S.
            for (int i = 0; i < L; i++) {
                putchar(S[i]);
            }
            putchar('\n');
            return 0;
        }
    }

    return 0;
}
